contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _val) public payable {
        bool setReverted;
        c.SetMinSum(_val); bool __rev0 = __ESBMC_reverted(); if (__rev0) { setReverted = true; } else { setReverted = false; }
        uint afterSetMin = c.MinSum(); if (__ESBMC_reverted()) return;
        bool initReverted;
        c.Initialized(); bool __rev1 = __ESBMC_reverted(); if (__rev1) { initReverted = true; } else { initReverted = false; }
        assert(!setReverted && afterSetMin == _val && !initReverted);
    }

    receive() external payable {}
}

