// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 _val) internal {
        bool setReverted;
        try c.SetMinSum(_val) { setReverted = false; } catch { setReverted = true; }
        uint256 afterSetMin;
        try c.MinSum() returns (uint256 __r) { afterSetMin = __r; } catch { return; }
        bool initReverted;
        try c.Initialized() { initReverted = false; } catch { initReverted = true; }
        assertTrue(!setReverted && afterSetMin == _val && !initReverted);
    }

    function testFuzz_run(uint256 _val) public {
        _run(_val);
    }

    receive() external payable {}
}
